def _compare_with_regex(request_headers: Union[Mapping[Any, Any], Any]) -> bool:
        if strict_match and len(request_headers) != len(headers):
            return False

        for k, v in headers.items(): #  [STATE] 1 [/STATE]
            if request_headers.get(k) is not None:
                if isinstance(v, re.Pattern):
                    if re.match(v, request_headers[k]) is None:
                        return False
                else:
                    if not v == request_headers[k]:
                        return False
            elif strict_match:
                return False

        return True

_compare_with_regex({'Accept': 'application/json'}, {'Accept': 'application/json'}, False)

def _replace_unspecified_values(htype: str, htype_overwrite: dict):
    """Replaces ``UNSPECIFIED`` values in ``htype_overwrite`` with the ``htype``'s defaults."""

    defaults = HTYPE_CONFIGURATIONS[htype] # [STATE] defaults = {'dtype': None, 'sample_compression': None, 'chunk_compression': None, 'typestr': None, 'max_chunk_size': None, 'tiling_threshold': None, 'is_sequence': False, 'is_link': False, 'hidden': False, 'links': None, 'verify': False} [/STATE]

    for k, v in htype_overwrite.items(): #  [STATE] 8 [/STATE]
        if isinstance(v, str) and v == UNSPECIFIED:
            htype_overwrite[k] = defaults[k] #  [STATE] htype_overwrite = {'sample_compression': None, 'chunk_compression': 'unspecified', 'dtype': 'int64', 'hidden': True, 'max_chunk_size': 4000000, 'is_sequence': False, 'is_link': False, 'verify': True} [/STATE] [STATE] htype_overwrite = {'sample_compression': None, 'chunk_compression': None, 'dtype': 'int64', 'hidden': True, 'max_chunk_size': 4000000, 'is_sequence': False, 'is_link': False, 'verify': True} [/STATE]

    if htype in ("json", "list", "text", "intrinsics") and not htype_overwrite["dtype"]:
        htype_overwrite["dtype"] = HTYPE_CONFIGURATIONS[htype]["dtype"]

